{
  "body": {
    "authority_unchanged": true,
    "engineering_blockers": [
      "Exact physical DUT marking, package, orderable suffix, and package-specific pinout.",
      "Exact programmer identity, voltage levels under load, supported clock rate, and timing behavior.",
      "Selected TXU0304 orderable package, footprint, availability, and assembly constraints.",
      "Complete VIH/VIL/VOH/VOL and propagation-delay timing budget at the selected supplies and load.",
      "Local 1.8 V supply implementation, current budget, sequencing, decoupling, protection, and OE behavior.",
      "Schematic/ERC/PCB/DRC results and all physical measurements."
    ],
    "ok": true,
    "physical_authority_granted": false,
    "pre_fabrication_plan": {
      "actions": [
        {
          "action_id": "resolve-identities",
          "depends_on": [],
          "description": "Capture actual DUT marking, package and suffix; reconcile to package-specific manufacturer pinout. Identify exact programmer and obtain its guaranteed interface and timing specifications. Select exact TXU0304 orderable package, footprint, availability and assembly constraints.",
          "source_refs": [
            {
              "claim_id": "dut-package-dependent-pinout",
              "source_id": "src-dut-datasheet"
            },
            {
              "claim_id": "txu-fixed-direction-map",
              "source_id": "src-translator-fixed-datasheet"
            }
          ],
          "status": "pending"
        },
        {
          "action_id": "close-budgets",
          "depends_on": [
            "resolve-identities"
          ],
          "description": "Complete worst-case logic-level, load and SPI timing budgets from additional traceable evidence; choose SPI mode and maximum clock only when supported.",
          "source_refs": [
            {
              "claim_id": "dut-standard-spi-directions",
              "source_id": "src-dut-datasheet"
            },
            {
              "claim_id": "txu-spi-example-not-component-spec",
              "source_id": "src-translator-fixed-datasheet"
            }
          ],
          "status": "pending"
        },
        {
          "action_id": "design-supply-controls",
          "depends_on": [
            "resolve-identities"
          ],
          "description": "Specify local 1.8 V regulator implementation, current and tolerance budget, decoupling, sequencing, protection, common return and OE bias/control. Resolve unused DUT pins and inactive CS behavior from exact device documentation; review partial-power/backfeed behavior.",
          "source_refs": [
            {
              "claim_id": "dut-operating-supply",
              "source_id": "src-dut-datasheet"
            },
            {
              "claim_id": "dut-pin-absolute-maximum",
              "source_id": "src-dut-datasheet"
